import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {string} meshUrl
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {Array<{event:string,effect:string}>} interactions
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>THREE.Object3D} glbLoader
 * @property {Record<string,Function>} primitives
 */

export default function createNode(config, ctx) {
  // root container
  const root = new THREE.Object3D();

  // ------------------------------------------------------------------------
  // Load mesh (synchronously, cached)
  // ------------------------------------------------------------------------
  const glb = ctx.glbLoader(config.meshUrl);
  let meshObject;
  if (glb && glb.scene) {
    meshObject = glb.scene;
  } else if (glb && glb.isObject3D) {
    meshObject = glb;
  } else {
    meshObject = new THREE.Object3D(); // fallback empty object
  }
  root.add(meshObject);

  // ------------------------------------------------------------------------
  // Apply placement transforms
  // ------------------------------------------------------------------------
  const pos = config.position ?? { x: 0, y: 0, z: 0 };
  const rot = config.rotation ?? { x: 0, y: 0, z: 0 };
  const scl = config.scale ?? { x: 1, y: 1, z: 1 };
  root.position.set(pos.x, pos.y, pos.z);
  root.rotation.set(rot.x, rot.y, rot.z);
  root.scale.set(scl.x, scl.y, scl.z);

  // ------------------------------------------------------------------------
  // Apply cinematic primitives
  // ------------------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(root, prim.params ?? {});
      }
    }
  }

  // ------------------------------------------------------------------------
  // Interaction handling (GSAP timelines)
  // ------------------------------------------------------------------------
  const hoverRiseAmount = 0.15; // scene units
  const hoverDuration = 0.7; // seconds, matches rise-in preset
  const hoverEase = 'power3.out';

  const hoverTimeline = gsap.timeline({ paused: true, defaults: { ease: hoverEase } });
  hoverTimeline.to(root.position, {
    y: `+=${hoverRiseAmount}`,
    duration: hoverDuration,
  });

  const pressScale = 0.97;
  const pressDuration = 0.12;
  const pressEase = 'back.out(1.7)';

  const pressTimeline = gsap.timeline({ paused: true, defaults: { ease: pressEase } });
  pressTimeline
    .to(root.scale, {
      x: pressScale,
      y: pressScale,
      z: pressScale,
      duration: pressDuration,
    })
    .to(
      root.scale,
      {
        x: 1,
        y: 1,
        z: 1,
        duration: pressDuration,
      },
      `>${pressDuration}`
    );

  // ------------------------------------------------------------------------
  // UserData – event handlers & cleanup
  // ------------------------------------------------------------------------
  root.userData.handlers = {
    hover: {
      enter: () => hoverTimeline.play(),
      leave: () => hoverTimeline.reverse(),
    },
    click: () => {
      // press animation
      pressTimeline.restart();

      // emit custom event for navigation
      root.dispatchEvent({ type: 'hub-home.select' });
    },
  };

  root.userData.cleanup = () => {
    hoverTimeline.kill();
    pressTimeline.kill();

    root.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        const mat = child.material;
        if (Array.isArray(mat)) {
          mat.forEach((m) => m.dispose && m.dispose());
        } else if (mat && mat.dispose) {
          mat.dispose();
        }
      }
    });
  };

  return root;
}
